1	/**
2	 * Публичный контракт пакета.
3	 *
4	 * Всё, что вызывают снаружи, проходит через этот файл. Внутренние модули друг на друга
5	 * ссылаются напрямую, но потребитель знает только отсюда.
6	 */
7	
8	export { add, formatRub, percent, rub, subtract } from './money.ts';
9	export type { Kopeck } from './money.ts';
10	
11	export { lineTotal, subtotal } from './lines.ts';
12	export type { Line } from './lines.ts';
13	
14	export type { Customer } from './customer.ts';
15	
16	export { DEFAULT_CONFIG, resolveConfig } from './config.ts';
17	export type { BillingConfig } from './config.ts';
18	
19	export { buildInvoice } from './invoice.ts';
20	export type { Invoice } from './invoice.ts';
21	
22	import { buildInvoice } from './invoice.ts';
23	import type { BillingConfig } from './config.ts';
24	import type { Customer } from './customer.ts';
25	import type { Invoice } from './invoice.ts';
26	import type { Line } from './lines.ts';
27	
28	/** Точка входа для вызывающих: выставить счёт. */
29	export function bill(
30	  number: string,
31	  customer: Customer,
32	  lines: readonly Line[],
33	  config?: Partial<BillingConfig>,
