19	export { buildInvoice } from './invoice.ts';
20	export type { Invoice } from './invoice.ts';
21	
22	import { buildInvoice } from './invoice.ts';
23	import type { BillingConfig } from './config.ts';
24	import type { Customer } from './customer.ts';
25	import type { Invoice } from './invoice.ts';
26	import type { Line } from './lines.ts';
27	
28	/** Точка входа для вызывающих: выставить счёт. */
29	export function bill(
30	  number: string,
31	  customer: Customer,
32	  lines: readonly Line[],
33	  config?: Partial<BillingConfig>,
34	): Invoice {
35	  return buildInvoice(number, customer, lines, config);
36	}
