/** Выставленный счёт — так его показывают покупателю и так же проверяют в поддержке. */
export interface Invoice {
  /** Номер счёта, присваивает вызывающий. */
  number: string;
  customer: Customer;
  lines: readonly Line[];
  /** Подытог по позициям, до налогов. */
  subtotal: Kopeck;
  /** Сумма к оплате. Сейчас совпадает с подытогом: налогов в расчёте пока нет. */
  total: Kopeck;
  /** Срок оплаты, в днях. Всегда задан: явная опция → конфиг площадки → встроенные 14. */
  dueDays: number;
}

/** Опции вызова, переопределяющие параметры счёта. */
export interface InvoiceOptions {
  /** Срок оплаты, в днях. Перебивает `defaultDueDays` из конфига площадки. */
  dueDays?: number;
}

/** Собрать счёт из позиций. */
export function buildInvoice(
  number: string,
  customer: Customer,
  lines: readonly Line[],
  config?: Partial<BillingConfig>,
  opts?: InvoiceOptions,
): Invoice {
  const resolved = resolveConfig(config); // конфиг читается здесь одним местом — переопределения действуют везде
  const dueDays = opts?.dueDays ?? resolved.defaultDueDays;
  const sub = subtotal(lines);
  return { number, customer, lines, subtotal: sub, total: sub, dueDays };
}

