1	/**
2	 * Позиции счёта.
3	 *
4	 * Позиция — то, за что платят: название, количество, цена единицы. Скидок и налогов здесь
5	 * нет намеренно: они применяются к счёту целиком на сборке, а не к строкам — иначе итог
6	 * перестаёт сходиться с подытогом на округлениях каждой строки.
7	 */
8	
9	import type { Kopeck } from './money.ts';
10	
11	export interface Line {
12	  title: string;
13	  /** Количество, целое. Дробного количества у нас нет — штучный товар. */
14	  qty: number;
15	  /** Цена единицы в копейках. */
16	  priceK: Kopeck;
17	}
18	
19	/** Стоимость позиции: количество × цена единицы. */
20	export function lineTotal(line: Line): Kopeck {
21	  return line.qty * line.priceK;
22	}
23	
24	/** Подытог счёта — сумма по позициям, до всяких налогов. */
25	export function subtotal(lines: readonly Line[]): Kopeck {
26	  let sum = 0;
27	  for (const line of lines) sum += lineTotal(line);
28	  return sum;
29	}
