1	/**
2	 * Тесты сборки счёта.
3	 *
4	 * Счёт без налогов: итог совпадает с подытогом, форма Invoice — {number, customer, lines,
5	 * subtotal, total}. Форма — контракт: её сверяют литералом, поэтому новые поля появляются
6	 * в Invoice только когда им есть что сказать.
7	 */
8	
9	import { deepStrictEqual, strictEqual } from 'node:assert/strict';
10	import { describe, it } from 'node:test';
11	
12	import { bill } from '../src/index.ts';
13	
14	const customer = { name: 'Иван', email: 'ivan@example.ru', phone: '+79001234567' };
15	
16	describe('сборка счёта', () => {
17	  it('итог совпадает с подытогом, пока налогов нет', () => {
18	    const inv = bill('СЧ-1', customer, [
19	      { title: 'Пакет', qty: 2, priceK: 333 },
20	      { title: 'Коробка', qty: 1, priceK: 334 },
21	    ]);
22	    strictEqual(inv.subtotal, 1_000);
23	    strictEqual(inv.total, 1_000);
24	  });
25	
26	  it('форма счёта — ровно пять полей', () => {
27	    const inv = bill('СЧ-2', customer, [{ title: 'Пакет', qty: 1, priceK: 100 }]);
28	    deepStrictEqual(Object.keys(inv).sort(), ['customer', 'lines', 'number', 'subtotal', 'total']);
29	    strictEqual(inv.number, 'СЧ-2');
30	  });
31	});
